select

from case_center_info
where 1=1

    and type = #{type,jdbcType=INTEGER}


    and case_id = #{caseId,jdbcType=BIGINT}


    and case_no = #{caseNo,jdbcType=VARCHAR}


    and case_name like concat('%',#{caseName,jdbcType=VARCHAR},'%')


    and case_tel = #{caseTel,jdbcType=VARCHAR}


    and case_state = #{caseState,jdbcType=INTEGER}


    and org_name = #{orgName,jdbcType=VARCHAR}


    and org_user_name like concat('%',#{orgUserName,jdbcType=VARCHAR},'%')


    and ins_officer_id = #{insOfficerId,jdbcType=BIGINT}


    and ins_officer_id in (SELECT b.user_id FROM user_insurance b where b.parent_id=#{insOfficerIds,jdbcType=BIGINT})


    and gradation_state = #{gradationState,jdbcType=INTEGER}


    and closed_state = #{closedState,jdbcType=INTEGER}

ORDER by create_time desc,case_state limit #{pageIndex} , #{pageSize}

