select * from (
SELECT a.*,b.case_id as p_case_id,b.case_type
from (select * from case_center_info WHERE gradation_state = 1


            and is_test_case = #{isTestcase,jdbcType=INTEGER}




            and is_test_case = 0


            and is_test_case = 1


) a
LEFT JOIN (select * from  payment_estimate_apply where case_id is not null GROUP BY case_id,case_type) b on a.case_id = b.case_id and a.type = b.case_type
) c where  c.p_case_id is not null

    and c.type = #{type,jdbcType=INTEGER}


    and c.case_no = #{caseNo,jdbcType=VARCHAR}


    and c.case_tel like concat('%',#{caseTel,jdbcType=VARCHAR},'%')


    and c.case_state = #{caseState,jdbcType=INTEGER}


    and c.org_id in (select u.org_id from user_risk_org u where u.user_id = #{userId,jdbcType=BIGINT})


    and find_in_set(c.org_id,SUBSTR((select getOrgList(#{orgId,jdbcType=BIGINT})) FROM 3 FOR 10000))


    and case_name like concat('%',#{caseName,jdbcType=VARCHAR},'%')



        and (c.negotiate_state = #{negotiateState,jdbcType=INTEGER} or c.negotiate_state is null)


        and c.negotiate_state = #{negotiateState,jdbcType=INTEGER}





ORDER by c.create_time desc,c.case_state

    limit #{pageIndex} , #{pageSize}

