select * from case_center_info
where hand_out_flag in (2,5,6)

    and gradation_state = #{gradationState,jdbcType=BIGINT}


    and case_name like concat('%',#{caseName,jdbcType=VARCHAR},'%')


    and case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')


    and hand_out_flag = #{handOutFlag,jdbcType=VARCHAR}



        and is_test_case = #{isTestcase,jdbcType=INTEGER}




        and is_test_case = 0


        and is_test_case = 1


and delete_flag !=1
ORDER by create_time desc limit #{pageIndex} , #{pageSize}

